/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-hero-instructor .sl-bg-primary-subtle { background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) !important; }
.sl-hero-instructor .sl-btn-primary { background-color: var(--smartlearn-btn-bg) !important; border-color: var(--smartlearn-btn-bg) !important; color: var(--smartlearn-btn-text, #ffffff) !important; }
.sl-hero-instructor .sl-btn-primary:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important; filter: brightness(0.9); }
.sl-hero-instructor .sl-btn-outline-primary { border-color: var(--smartlearn-primary) !important; color: var(--smartlearn-primary) !important; }
.sl-hero-instructor .sl-btn-outline-primary:hover { background-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-border-primary { border-color: var(--smartlearn-primary) !important; }
.sl-hero-instructor {
    min-height: 85vh;
}
.sl-hero-instructor .sl-title-tracking {
    letter-spacing: -0.03em;
}
.sl-hero-instructor .sl-pulsing-dot {
    animation: slPulseRed 1.5s infinite;
}
@keyframes slPulseRed {
    0% { box-shadow: 0 0 0 0 rgba(220, 53, 69, 0.7); }
    70% { box-shadow: 0 0 0 10px rgba(220, 53, 69, 0); }
    100% { box-shadow: 0 0 0 0 rgba(220, 53, 69, 0); }
}
.sl-hero-instructor .sl-blob-bg {
    animation: slScalePulse 6s ease-in-out infinite alternate;
}
@keyframes slScalePulse {
    0% { transform: translate(-50%, -50%) scale(1); }
    100% { transform: translate(-50%, -50%) scale(1.1); }
}
.sl-hero-instructor .sl-orbit-badge {
    transition: transform 0.3s ease;
}
.sl-hero-instructor .sl-orbit-badge:hover {
    transform: scale(1.05) translateY(-5px) !important;
}
.sl-hero-instructor .sl-badge-1 {
    animation: slFloatBadge 5s ease-in-out infinite;
}
.sl-hero-instructor .sl-badge-2 {
    animation: slFloatBadge 6s ease-in-out infinite 1s;
}
.sl-hero-instructor .sl-badge-3 {
    animation: slFloatBadge 4s ease-in-out infinite 2s;
}
@keyframes slFloatBadge {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-15px); }
}

